/**
 * Scoped API keys (generated by Quickback — do not edit).
 * Docs: https://docs.quickback.dev/platform/auth/api-keys#scopes
 */
import type { BetterAuthPlugin } from 'better-auth';
import { APIError, createAuthMiddleware } from 'better-auth/api';
import { API_KEY_TABLE_NAME, defaultKeyHasher } from '@better-auth/api-key';

/** Display prefix for new keys (`plugins.apiKey.prefix`). */
export const API_KEY_PREFIX = "softwear_";

/** Resources a `<resource>:read` / `<resource>:write` scope may name. */
export const API_KEY_SCOPE_RESOURCES: readonly string[] = ["bag-items","custom-view","order-lines","orders","products","promo-codes","promo-redemptions","restock-requests","saved-styles","stock","subscribers"];

const API_BASE = "/api/v1";
const AUTH_BASE = "/auth/v1";
const MCP_PATH = '/mcp';

/**
 * A prefixed key may also arrive as `Authorization: Bearer <key>` — the one
 * channel the MCP endpoint forwards. Unprefixed (pre-prefix) keys only work
 * through `x-api-key`. The prefix can't collide with session tokens or
 * JWTs (see the compiler's prefix rule).
 */
export function apiKeyFromAuthorization(header: string | null | undefined): string | undefined {
  return header?.startsWith(`Bearer ${API_KEY_PREFIX}`) ? header.slice(7) : undefined;
}

/**
 * Validate scopes at key creation/update. `undefined` = no scopes (full
 * owner role). Anything else must be a non-empty array of known scopes.
 */
export function assertApiKeyScopes(raw: unknown): void {
  if (raw === undefined) return;
  if (!Array.isArray(raw) || raw.length === 0) {
    throw new Error('metadata.scopes must be a non-empty array of scope strings (omit it for a full-access key).');
  }
  for (const scope of raw) {
    if (scope === 'read' || scope === 'write') continue;
    const m = typeof scope === 'string' ? /^(.+):(read|write)$/.exec(scope) : null;
    if (!m || !API_KEY_SCOPE_RESOURCES.includes(m[1])) {
      throw new Error(
        `Unknown API key scope ${JSON.stringify(scope)}. Valid: read, write, or <resource>:read|write for ${API_KEY_SCOPE_RESOURCES.join(', ') || '(no resources)'}.`,
      );
    }
  }
}

/** Request-time read: `undefined` = legacy full-role key; `null` = malformed (fail closed). */
export function readApiKeyScopes(metadata: unknown): string[] | undefined | null {
  if (!metadata || typeof metadata !== 'object' || !('scopes' in metadata)) return undefined;
  const raw = (metadata as { scopes: unknown }).scopes;
  return Array.isArray(raw) && raw.length > 0 && raw.every((s) => typeof s === 'string') ? raw : null;
}

/**
 * Does a scoped key cover this request? Under the API base the request needs
 * `<mode>` or `<resource>:<mode>`. The auth base is allowed (a key acts
 * there only as the get-session whoami). Every other surface — storage,
 * realtime, webhooks, FGA, public discovery — is refused to scoped keys.
 */
export function checkApiKeyScopes(
  scopes: readonly string[],
  method: string,
  path: string,
): { allowed: boolean; required: string | null } {
  const mode = method === 'GET' || method === 'HEAD' || method === 'OPTIONS' ? 'read' : 'write';
  if (path === AUTH_BASE || path.startsWith(AUTH_BASE + '/')) return { allowed: true, required: null };
  // MCP: each tools/call re-enters the app with the same key against the
  // tool's REST route, where its scope is checked for real.
  if (path === MCP_PATH) return { allowed: true, required: null };
  if (path !== API_BASE && !path.startsWith(API_BASE + '/')) return { allowed: false, required: null };
  const resource = path.slice(API_BASE.length + 1).split('/')[0];
  const required = resource ? `${resource}:${mode}` : mode;
  return { allowed: scopes.includes(mode) || scopes.includes(required), required };
}

/**
 * `customAPIKeyValidator`: runs inside BOTH Better Auth key lanes — the
 * middleware's `verifyApiKey` and the `/get-session` whoami — so a banned
 * (or deleted) owner's keys stop working everywhere. Ban expiry follows the
 * admin plugin: a past `banExpires` no longer counts.
 */
export async function apiKeyOwnerActive({ ctx, key }: { ctx: any; key: string }): Promise<boolean> {
  const row = await ctx.context.adapter.findOne({
    model: API_KEY_TABLE_NAME,
    where: [{ field: 'key', value: await defaultKeyHasher(key) }],
  });
  if (!row) return true; // unknown key — Better Auth rejects it next.
  const owner = await ctx.context.internalAdapter.findUserById(row.referenceId);
  if (!owner) return false;
  const banExpires = owner.banExpires ? new Date(owner.banExpires).getTime() : undefined;
  if (owner.banned === true && (banExpires === undefined || banExpires > Date.now())) {
    throw new APIError('FORBIDDEN', { message: 'API key owner is banned', code: 'USER_BANNED' });
  }
  return true;
}

/** Rejects unknown/malformed scopes on `/api-key/create` and `/api-key/update`. */
export const apiKeyScopesPlugin = {
  id: 'quickback-api-key-scopes',
  hooks: {
    before: [{
      matcher: (ctx) => ctx.path === '/api-key/create' || ctx.path === '/api-key/update',
      handler: createAuthMiddleware(async (ctx) => {
        const metadata = (ctx.body as { metadata?: unknown } | undefined)?.metadata;
        if (!metadata || typeof metadata !== 'object') return;
        try {
          assertApiKeyScopes((metadata as { scopes?: unknown }).scopes);
        } catch (e) {
          throw new APIError('BAD_REQUEST', { message: (e as Error).message, code: 'INVALID_API_KEY_SCOPES' });
        }
      }),
    }],
  },
} satisfies BetterAuthPlugin;

